    "home_faq_title": "অকৌসৰ পুছৃ জানৃ ৱালৃ পৌৰশৌন",
    "home_faq_subtitle": "Everything you need to know about NutriAI clinical assessments.",
    "home_faq_q1": "এআঈ পুষ্টি মূল্যাঙ্কন কচতনা নিখুঁত হৈ?",
    "home_faq_a1": "NutriAI achieves a 94.8% F1-score validation on held-out NHANES clinical datasets. Our Random Forest ensemble is trained on thousands of real patient records.",
    "home_faq_q2": "তেজৰ পৰীক্ষাৰ পিডিএফ ৰিপৰ্ট পোনপটীয়াকৈ আপলোড কৰিব পাৰিমনে?",
    "home_faq_a2": "Yes! Our multi-modal Gemini Vision OCR parses lab PDF files and auto-fills your blood marker values for instant deficiency risk analysis.",
    "home_faq_q3": "কৌযা নৌযুটৌৰি-এআঈ শাকাহাৰি ঔৰ ৱিগন আহাৰ কা সমৰৌথন কৰতা হৈ?",
    "home_faq_a3": "Absolutely! Our meal recommender includes strict biological nutritional shields ensuring complete protein, iron, and B12 adequacy for all dietary preferences.",
    "home_faq_q4": "PWA ঐপ বচনা ঐপ সৌটৈৰ ডাউনলৈড কৃ কৈসৃ কাম কৰতা হৈ?",
    "home_faq_a4": "NutriAI is built with Progressive Web App (PWA) technology. Simply visit the site in Chrome or Safari and tap 'Install' to get a native app-like experience.",
