    "home_faq_a1": "NHANES ಕ್ಲಿನಿಕಲ್ ಡೇಟಾಸೆಟ್‌ಗಳಲ್ಲಿ NutriAI 94.8% F1-ಸ್ಕೋರ್ ಮೌಲ್ಯೀಕರಣವನ್ನು ಸಾಧಿಸುತ್ತದೆ. ನಮ್ಮ ರಾಂಡಮ್ ಫಾರೆಸ್ಟ್ ಸಮೂಹವು ಸಾವಿರಾರು ನೈಜ ರೋಗಿಗಳ ದಾಖಲೆಗಳ ಮೇಲೆ ತರಬೇತಿ ಪಡೆದಿದೆ.",
