    "home_faq_a2": "ಹೌದು! ನಮ್ಮ ಬಹು-ಮಾದರಿ ಜೆಮಿನಿ ವಿಷನ್ OCR ಲ್ಯಾಬ್ PDF ಫೈಲ್‌ಗಳನ್ನು ಪಾರ್ಸ್ ಮಾಡುತ್ತದೆ ಮತ್ತು ತ್ವರಿತ ಕೊರತೆಯ ಅಪಾಯದ ವಿಶ್ಲೇಷಣೆಗಾಗಿ ನಿಮ್ಮ ರಕ್ತದ ಮಾರ್ಕರ್ ಮೌಲ್ಯಗಳನ್ನು ಸ್ವಯಂ ತುಂಬಿಸುತ್ತದೆ.",
    "home_faq_q3": "ಕ್ಯಾ ನ್ಯೂಟ್ರೀ-ಎಆಈ ಶಾಕಾಹಾರೀ ಔರ ವೀಗನ ಆಹಾರ ಕಾ ಸಮರ್ಥನ ಕರತಾ ಹೈ?",
    "home_faq_a3": "ಸಂಪೂರ್ಣವಾಗಿ! ನಮ್ಮ ಊಟದ ಶಿಫಾರಸುದಾರರು ಎಲ್ಲಾ ಆಹಾರದ ಆದ್ಯತೆಗಳಿಗೆ ಸಂಪೂರ್ಣ ಪ್ರೋಟೀನ್, ಕಬ್ಬಿಣ ಮತ್ತು B12 ಸಮರ್ಪಕತೆಯನ್ನು ಖಾತ್ರಿಪಡಿಸುವ ಕಟ್ಟುನಿಟ್ಟಾದ ಜೈವಿಕ ಪೌಷ್ಟಿಕಾಂಶದ ಗುರಾಣಿಗಳನ್ನು ಒಳಗೊಂಡಿದೆ.",
