    "home_faq_subtitle": "NutriAI ക്ലിനിക്കൽ വിലയിരുത്തലുകളെ കുറിച്ച് നിങ്ങൾ അറിയേണ്ടതെല്ലാം.",
    "home_faq_q1": "എആഈ പൊഷണ മൂല്യാംകന കിതനാ സടീക ഹൈ?",
    "home_faq_a1": "NHANES ക്ലിനിക്കൽ ഡാറ്റാസെറ്റുകളിൽ NutriAI 94.8% F1-സ്കോർ മൂല്യനിർണ്ണയം നേടുന്നു. ഞങ്ങളുടെ റാൻഡം ഫോറസ്റ്റ് സംഘം ആയിരക്കണക്കിന് യഥാർത്ഥ രോഗികളുടെ റെക്കോർഡുകളിൽ പരിശീലനം നേടിയിട്ടുണ്ട്.",
    "home_faq_q2": "എനിക്ക് രക്തപരിശോധനയുടെ PDF റിപ്പോർട്ടുകൾ നേരിട്ട് അപ്‌ലോഡ് ചെയ്യാൻ കഴിയുമോ?",
    "home_faq_a2": "അതെ! ഞങ്ങളുടെ മൾട്ടി-മോഡൽ ജെമിനി വിഷൻ OCR ലാബ് PDF ഫയലുകൾ പാഴ്‌സ് ചെയ്യുകയും തൽക്ഷണ ന്യൂനത അപകടസാധ്യത വിശകലനത്തിനായി നിങ്ങളുടെ രക്ത മാർക്കർ മൂല്യങ്ങൾ സ്വയമേവ പൂരിപ്പിക്കുകയും ചെയ്യുന്നു.",
    "home_faq_q3": "ക്യാ ന്യൂട്രീ-എആഈ ശാകാഹാരീ ഔര വീഗന ആഹാര കാ സമര്ഥന കരതാ ഹൈ?",
    "home_faq_a3": "തികച്ചും! എല്ലാ ഭക്ഷണ മുൻഗണനകൾക്കും സമ്പൂർണ്ണ പ്രോട്ടീൻ, ഇരുമ്പ്, ബി 12 എന്നിവയുടെ പര്യാപ്തത ഉറപ്പാക്കുന്ന കർശനമായ ജൈവ പോഷകാഹാര ഷീൽഡുകൾ ഞങ്ങളുടെ ഭക്ഷണ ശുപാർശയിൽ ഉൾപ്പെടുന്നു.",
    "home_faq_q4": "PWA ഐപ ബിനാ ഐപ സ്ടൊര ഡാഉനലൊഡ കേ കൈസേ കാമ കരതാ ഹൈ?",
    "home_faq_a4": "പ്രോഗ്രസീവ് വെബ് ആപ്പ് (PWA) സാങ്കേതികവിദ്യ ഉപയോഗിച്ചാണ് NutriAI നിർമ്മിച്ചിരിക്കുന്നത്. ഒരു നേറ്റീവ് ആപ്പ് പോലുള്ള അനുഭവം ലഭിക്കാൻ Chrome-ലോ Safari-ലോ സൈറ്റ് സന്ദർശിച്ച് 'ഇൻസ്റ്റാൾ' ടാപ്പ് ചെയ്യുക.",
