    "home_faq_title": "ଅକ୍ସର ପୂଛେ ଜାନେ ଵାଲେ ପ୍ରଶ୍ନ",
    "home_faq_subtitle": "NutriAI କ୍ଲିନିକାଲ୍ ମୂଲ୍ୟାଙ୍କନ ବିଷୟରେ ଆପଣ ଯାହାକିଛି ଜାଣିବା ଆବଶ୍ୟକ କରନ୍ତି |",
    "home_faq_q1": "ଏଆଈ ପୋଷଣ ମୂଲ୍ୟାଙ୍କନ କିତନା ସଠିକ୍ ହୈ?",
    "home_faq_a1": "NutriAI ଏକ 94.8% F1- ସ୍କୋର ବ valid ଧତା ହାସଲ କରିଥିବା NHANES କ୍ଲିନିକାଲ୍ ଡାଟାବେସରେ ହାସଲ କରେ | ଆମର ରାଣ୍ଡମ ଫରେଷ୍ଟ ସଂଗୀତ ହଜାର ହଜାର ପ୍ରକୃତ ରୋଗୀ ରେକର୍ଡ ଉପରେ ତାଲିମ ପ୍ରାପ୍ତ |",
    "home_faq_q2": "ମୁଁ ସିଧାସଳଖ ରକ୍ତ ପରୀକ୍ଷା PDF ରିପୋର୍ଟ ଅପଲୋଡ୍ କରିପାରିବି କି?",
    "home_faq_a2": "ହଁ! ଆମର ମଲ୍ଟି-ମୋଡାଲ୍ ମିଥୁନ ଭିଜନ OCR ଲ୍ୟାବ PDF ଫାଇଲଗୁଡ଼ିକୁ ବିଶ୍ଳେଷଣ କରେ ଏବଂ ତତକ୍ଷଣାତ୍ ଅଭାବର ବିପଦ ବିଶ୍ଳେଷଣ ପାଇଁ ତୁମର ରକ୍ତ ମାର୍କର ମୂଲ୍ୟକୁ ସ୍ auto ତ - ପୂରଣ କରେ |",
    "home_faq_q3": "କ୍ଯା ନ୍ଯୂଟ୍ରୀ-ଏଆଈ ଶାକାହାରୀ ଔର ଵୀଗନ ଆହାର କା ସମର୍ଥନ କରତା ହୈ?",
    "home_faq_a3": "ଅବଶ୍ୟ! ଆମର ଭୋଜନ ସୁପାରିଶରେ ସମସ୍ତ ଖାଦ୍ୟପେୟ ପସନ୍ଦ ପାଇଁ ସମ୍ପୂର୍ଣ୍ଣ ପ୍ରୋଟିନ୍, ଆଇରନ୍, ଏବଂ B12 ପର୍ଯ୍ୟାପ୍ତତା ନିଶ୍ଚିତ କରୁଥିବା କଠୋର ଜ bi ବିକ ପୁଷ୍ଟିକର ield ାଲ ଅନ୍ତର୍ଭୁକ୍ତ |",
    "home_faq_q4": "PWA ଐପ ବିନା ଐପ ସ୍ଟୋର ଡାଉନଲୋଡ କେ କୈସେ କାମ କରତା ହୈ?",
    "home_faq_a4": "NutriAI ପ୍ରଗତିଶୀଳ ୱେବ୍ ଆପ୍ (PWA) ଟେକ୍ନୋଲୋଜି ସହିତ ନିର୍ମିତ | କ୍ରୋମ୍ କିମ୍ବା ସଫାରିରେ ଥିବା ସାଇଟ୍ ପରିଦର୍ଶନ କରନ୍ତୁ ଏବଂ ଏକ ସ୍ଥାନୀୟ ଆପ୍ ପରି ଅଭିଜ୍ଞତା ପାଇବାକୁ 'ସଂସ୍ଥାପନ' ଟ୍ୟାପ୍ କରନ୍ତୁ |",
    "home_pwa_banner_title": "ଯେକୌଣସି ଡିଭାଇସରେ ନିଉଟ୍ରି-AI ଆପ୍ ଇନଷ୍ଟଲ୍ କରନ୍ତୁ",
